#!/usr/bin/env swift

import Foundation

let typeCount = 2_000
let fieldsPerType = 5
let chunkSize = 50
let outputPath = CommandLine.arguments.dropFirst().first
    ?? "Benchmarks/GraphitiBenchmarks/MassiveSchema.generated.swift"

func typeName(_ index: Int) -> String {
    String(format: "MassiveType%04d", index)
}

var output = """
// Generated by Benchmarks/GenerateMassiveSchema.swift. Do not edit by hand.

import Graphiti

enum MassiveSchemaFixture {
    static let typeCount = \(typeCount)
    static let fieldsPerType = \(fieldsPerType)
    static let modelFieldCount = typeCount * fieldsPerType

    static func components() -> [Component<MassiveResolver, MassiveContext>] {
        var components: [Component<MassiveResolver, MassiveContext>] = []
        components.reserveCapacity(typeCount + 1)

"""

for start in stride(from: 0, to: typeCount, by: chunkSize) {
    let end = min(start + chunkSize, typeCount)
    output += "        components += components\(String(format: "%04d", start))to\(String(format: "%04d", end - 1))()\n"
}

output += """
        components.append(
            Query<MassiveResolver, MassiveContext> {
                Field("hot", at: \\.hot)
                Field("sample", at: \\.sample)
            }
        )
        return components
    }
}

struct MassiveContext: Sendable {}

struct MassiveResolver: Sendable {
    let hot = "Graphiti"
    let sample = \(typeName(typeCount - 1))()
}

struct MassiveAPI: API, Sendable {
    let resolver = MassiveResolver()
    let schema: Schema<MassiveResolver, MassiveContext>

    init() throws {
        schema = try Schema(components: MassiveSchemaFixture.components())
    }
}

"""

for index in 0 ..< typeCount {
    output += "struct \(typeName(index)): Sendable {\n"
    for field in 0 ..< fieldsPerType {
        output += "    let field\(field) = \(field)\n"
    }
    output += "}\n\n"
}

for start in stride(from: 0, to: typeCount, by: chunkSize) {
    let end = min(start + chunkSize, typeCount)
    output += "private func components\(String(format: "%04d", start))to\(String(format: "%04d", end - 1))() -> [Component<MassiveResolver, MassiveContext>] {\n"
    output += "    [\n"
    for index in start ..< end {
        output += "        Type(resolver: MassiveResolver.self, context: MassiveContext.self, \(typeName(index)).self, fields: [\n"
        for field in 0 ..< fieldsPerType {
            output += "            Field(\"field\(field)\", at: \\\(typeName(index)).field\(field))\(field == fieldsPerType - 1 ? "" : ",")\n"
        }
        output += "        ])\(index == end - 1 ? "" : ",")\n"
    }
    output += "    ]\n"
    output += "}\n\n"
}

output.removeLast()
try output.write(toFile: outputPath, atomically: true, encoding: .utf8)
print("Generated \(typeCount) types and \(typeCount * fieldsPerType) fields at \(outputPath)")
